const response = $input.first().json;
const pages = response.results || [];
const today = $now.toFormat('yyyy-MM-dd');

const getName = (page) => page.properties?.Name?.title?.[0]?.text?.content || 'Unnamed task';
const getPriority = (page) => page.properties?.Priority?.select?.name || null;
const getDue = (page) => page.properties?.Due?.date?.start || null;
const getStatus = (page) => page.properties?.Status?.select?.name || 'Unknown';

if (pages.length === 0) {
  const dateStr = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: '2-digit', month: 'long' });
  return [{
    json: {
      date: today,
      generatedAt: new Date().toISOString(),
      taskCount: 0,
      overdueCount: 0,
      todayCount: 0,
      inProgressCount: 0,
      overdueTasks: [],
      todayTasks: [],
      inProgressTasks: [],
      emailSubject: `[ADHD System] Daily Briefing — ${new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short' })} — Clear day`,
      emailBody: `Daily Briefing — ${dateStr}\n\nClear day — no tasks due or in progress.\n\nUse this intentionally. What is the one thing you want to move forward today?\n\nOpen your dashboard to capture it.`
    }
  }];
}

const todayTasks = [];
const overdueTasks = [];
const inProgressTasks = [];

for (const page of pages) {
  const due = getDue(page);
  const task = {
    id: page.id,
    name: getName(page),
    priority: getPriority(page),
    status: getStatus(page),
    due,
    url: page.url
  };
  if (due && due < today) {
    overdueTasks.push(task);
  } else if (due === today) {
    todayTasks.push(task);
  } else {
    inProgressTasks.push(task);
  }
}

const priorityOrder = { 'RED': 0, 'AMBER': 1, 'GREEN': 2 };
const sortByPriority = (a, b) => (priorityOrder[a.priority] ?? 3) - (priorityOrder[b.priority] ?? 3);
overdueTasks.sort(sortByPriority);
todayTasks.sort(sortByPriority);

const payload = {
  date: today,
  generatedAt: new Date().toISOString(),
  taskCount: pages.length,
  overdueCount: overdueTasks.length,
  todayCount: todayTasks.length,
  inProgressCount: inProgressTasks.length,
  overdueTasks: overdueTasks.slice(0, 10),
  todayTasks: todayTasks.slice(0, 10),
  inProgressTasks: inProgressTasks.slice(0, 5)
};

const dateStr = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: '2-digit', month: 'long' });
const lines = [`Daily Briefing — ${dateStr}`, ''];

if (overdueTasks.length > 0) {
  lines.push(`OVERDUE (${overdueTasks.length})`);
  overdueTasks.slice(0, 5).forEach(t => {
    lines.push(`  - ${t.name}${t.priority ? ` [${t.priority}]` : ''} — was due ${t.due}`);
  });
  if (overdueTasks.length > 5) lines.push(`  ... and ${overdueTasks.length - 5} more`);
  lines.push('');
}

if (todayTasks.length > 0) {
  lines.push(`TODAY (${todayTasks.length})`);
  todayTasks.slice(0, 5).forEach(t => {
    lines.push(`  - ${t.name}${t.priority ? ` [${t.priority}]` : ''}`);
  });
  if (todayTasks.length > 5) lines.push(`  ... and ${todayTasks.length - 5} more`);
  lines.push('');
}

if (inProgressTasks.length > 0) {
  lines.push(`IN PROGRESS (${inProgressTasks.length})`);
  inProgressTasks.slice(0, 3).forEach(t => {
    lines.push(`  - ${t.name}`);
  });
  lines.push('');
}

lines.push('Open your dashboard to review and start your day.');

const emailSubject = `[ADHD System] Daily Briefing — ${new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short' })} — ${overdueTasks.length > 0 ? overdueTasks.length + ' overdue' : todayTasks.length + ' today'}`;

return [{ json: { ...payload, emailSubject, emailBody: lines.join('\n') } }];
